-- Read-only post-verification; exact Dashboard target requires external attestation.
BEGIN TRANSACTION READ ONLY;
WITH roles AS (SELECT (SELECT oid FROM pg_catalog.pg_roles WHERE rolname='fid_function_owner') owner_oid,(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='service_role') service_oid,(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='anon') anon_oid,(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='authenticated') authenticated_oid),
fn AS (SELECT count(p.oid)::integer function_count,(array_agg(p.oid))[1] function_oid,bool_and(p.proowner=r.owner_oid AND p.prosecdef AND p.provolatile='v' AND p.proparallel='u' AND p.proconfig=ARRAY['search_path=pg_catalog, fid']::text[]) security_exact FROM roles r LEFT JOIN pg_catalog.pg_namespace n ON n.nspname='fid' LEFT JOIN pg_catalog.pg_proc p ON p.pronamespace=n.oid AND p.proname='fid_execute_atomic_persistence_batch' AND pg_catalog.pg_get_function_identity_arguments(p.oid)='batch_id text, ordered_operations jsonb, requested_atomicity text, preconditions jsonb, expected_repository jsonb, idempotency jsonb, audit jsonb, source_refs jsonb'),
acl AS (SELECT r.*,f.*,count(*) FILTER(WHERE a.grantee=0 AND a.privilege_type='EXECUTE') direct_public,count(*) FILTER(WHERE a.grantee=r.owner_oid AND a.privilege_type='EXECUTE') direct_owner,count(*) FILTER(WHERE a.grantee=r.service_oid AND a.privilege_type='EXECUTE') direct_service,count(*) FILTER(WHERE a.grantee=r.anon_oid AND a.privilege_type='EXECUTE') direct_anon,count(*) FILTER(WHERE a.grantee=r.authenticated_oid AND a.privilege_type='EXECUTE') direct_authenticated,count(*) FILTER(WHERE a.privilege_type='EXECUTE') direct_total,count(*) FILTER(WHERE a.privilege_type='EXECUTE' AND a.is_grantable) grantable_total FROM roles r CROSS JOIN fn f LEFT JOIN pg_catalog.pg_proc p ON p.oid=f.function_oid LEFT JOIN LATERAL pg_catalog.aclexplode(p.proacl) a ON true GROUP BY r.owner_oid,r.service_oid,r.anon_oid,r.authenticated_oid,f.function_count,f.function_oid,f.security_exact),
rollback AS (SELECT (SELECT count(*) FROM fid.fid_persistence_migrations WHERE migration_id COLLATE "C" LIKE '%014%' OR migration_sequence=14 OR 'fid-014-identifier-issuance-transaction'=ANY(applied_migration_ids)) metadata_count,(SELECT count(*) FROM (VALUES(pg_catalog.to_regclass('fid.fid_identifier_reservations')::oid),(pg_catalog.to_regclass('fid.fid_identifier_issuance_ledger')::oid),(pg_catalog.to_regclass('fid.fid_identifier_issuance_idempotency')::oid),(pg_catalog.to_regprocedure('fid.fid_execute_prospect_identifier_issuance_transaction(text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,integer,text,text,text,jsonb,jsonb)')::oid)) x(oid) WHERE oid IS NOT NULL) object_count)
SELECT 'FID_ATOMIC_FUNCTION_ACL_POST_VERIFICATION_017C44'::text result_identity,'17C.44.1'::text result_version,
CASE WHEN function_count<>1 OR function_oid IS NULL OR owner_oid IS NULL OR service_oid IS NULL OR anon_oid IS NULL OR authenticated_oid IS NULL THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_STATE_UNRESOLVED' WHEN metadata_count<>0 OR object_count<>0 OR security_exact IS NOT TRUE OR grantable_total<>0 THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_STATE_INCONSISTENT_RECOVERY_REQUIRED' WHEN direct_public=0 AND direct_owner=0 AND direct_service=1 AND direct_anon=0 AND direct_authenticated=0 AND direct_total=1 AND NOT pg_catalog.has_function_privilege(anon_oid,function_oid,'EXECUTE') AND NOT pg_catalog.has_function_privilege(authenticated_oid,function_oid,'EXECUTE') AND pg_catalog.has_function_privilege(service_oid,function_oid,'EXECUTE') AND pg_catalog.has_function_privilege(owner_oid,function_oid,'EXECUTE') THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_FULLY_APPLIED' ELSE 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_STATE_INCONSISTENT_RECOVERY_REQUIRED' END classification,
direct_public>0 public_direct_execute,direct_anon>0 anon_direct_execute,direct_authenticated>0 authenticated_direct_execute,direct_owner>0 owner_direct_acl_entry,true owner_derived_authority,direct_service>0 service_direct_execute,
CASE WHEN function_oid IS NULL THEN false ELSE pg_catalog.has_function_privilege(anon_oid,function_oid,'EXECUTE') END anon_effective_execute,CASE WHEN function_oid IS NULL THEN false ELSE pg_catalog.has_function_privilege(authenticated_oid,function_oid,'EXECUTE') END authenticated_effective_execute,CASE WHEN function_oid IS NULL THEN false ELSE pg_catalog.has_function_privilege(service_oid,function_oid,'EXECUTE') END service_effective_execute,
metadata_count::bigint migration_014_metadata_count,object_count::integer migration_014_object_count,true external_target_attestation_required,false overall_target_verified,true read_only,0::integer mutation_count
FROM acl CROSS JOIN rollback;
COMMIT;
